#pragma once

#include "aegistrack/core/types.hpp"

#include <cmath>
#include <cstdint>
#include <optional>
#include <stdexcept>

namespace aegistrack {

/**
 * @brief Represents a single timestamped observation generated by a sensor.
 */
struct Measurement {
    std::uint64_t measurement_id{0};
    SensorId sensor_id;
    SensorType sensor_type{SensorType::Radar};
    TimestampSec capture_timestamp{0.0};
    TimestampSec arrival_timestamp{0.0};
    VectorXd z;
    MatrixXd R;
    Vector2d sensor_position{Vector2d::Zero()};
    bool is_valid{true};

    /// Optional telemetry identity transmitted in GNSS packets (ignored in anonymous mode).
    std::optional<ObjectId> telemetry_source_id{std::nullopt};

    /// Evaluation-only metadata (strictly inaccessible to tracker/associator logic).
    std::optional<ObjectId> evaluation_ground_truth_id{std::nullopt};
    bool is_clutter{false};

    [[nodiscard]] Eigen::Index dimension() const noexcept {
        return z.size();
    }

    [[nodiscard]] bool isConsistent() const noexcept {
        if (!is_valid || z.size() == 0 || R.rows() != z.size() || R.cols() != z.size()) {
            return false;
        }
        if (!z.allFinite() || !R.allFinite() || !sensor_position.allFinite() ||
            !std::isfinite(capture_timestamp) || !std::isfinite(arrival_timestamp)) {
            return false;
        }
        if (sensor_type == SensorType::Radar && (z.size() != 2 || z(0) < 0.0)) {
            return false;
        }
        if (sensor_type == SensorType::Gnss && z.size() != 2) {
            return false;
        }
        if (sensor_type == SensorType::BearingOnly && z.size() != 1) {
            return false;
        }
        return true;
    }

    /**
     * @brief Projects measurement into 2D Cartesian world coordinates (px, py) for
     * track initialization and visualization.
     */
    [[nodiscard]] Vector2d toCartesianPosition() const {
        if (!isConsistent()) {
            throw std::invalid_argument("Measurement::toCartesianPosition on invalid measurement");
        }
        if (sensor_type == SensorType::Gnss) {
            return Vector2d{z(0), z(1)};
        }
        if (sensor_type == SensorType::Radar) {
            const double r = z(0);
            const double theta = z(1);
            return sensor_position + Vector2d{r * std::cos(theta), r * std::sin(theta)};
        }
        throw std::invalid_argument("BearingOnly measurement has no unique Cartesian position");
    }

    /**
     * @brief Propagates measurement covariance R into 2D Cartesian covariance R_xy = J * R * J^T
     * for track initialization.
     */
    [[nodiscard]] Matrix2d toCartesianCovariance() const {
        if (!isConsistent()) {
            throw std::invalid_argument("Measurement::toCartesianCovariance on invalid measurement");
        }
        if (sensor_type == SensorType::Gnss) {
            return R.topLeftCorner<2, 2>();
        }
        if (sensor_type == SensorType::Radar) {
            const double r = std::max(1.0, z(0));
            const double theta = z(1);
            const double c = std::cos(theta);
            const double s = std::sin(theta);
            Matrix2d J;
            J << c, -r * s,
                 s,  r * c;
            return J * R.topLeftCorner<2, 2>() * J.transpose();
        }
        throw std::invalid_argument("BearingOnly measurement has no 2D Cartesian covariance");
    }
};

}  // namespace aegistrack
